window.receiveProjectSource({"path": "test/unit/db/erd/parity.py", "lines": ["\"\"\"Comparison machinery for the ERD parity guard.", "", "Kept apart from the test modules so the guard (``test_erd_parity.py``) and the", "probes (``test_erd_parity_probes.py``) run the exact same code: a probe that", "re-implemented the comparison would prove nothing about the guard.", "", "Every function here is pure over ``(spec, metadata, registers, deferred)`` except", ":func:`comparisons_for`, :func:`binding_state_problems` and", ":func:`migration_trigger_problems`, which resolve a binding's metadata or trigger", "DDL through :mod:`common.erd.bindings` looked up at call time, so a probe can", "monkeypatch it.", "\"\"\"", "", "from __future__ import annotations", "", "import ast", "import re", "from collections.abc import Collection, Iterable, Mapping", "from dataclasses import dataclass", "from functools import lru_cache", "from pathlib import Path", "", "import sqlalchemy as sa", "from sqlalchemy.dialects import postgresql", "", "from common.erd import bindings as erd_bindings", "from common.erd.bindings import BindingState, ErdBinding, scan_schema_references", "from common.erd.model_spec import (", "    ErdSpec,", "    ErdSpecError,", "    ErdTable,", "    load_erd_spec,", "    normalize_check_sql,", "    normalize_comment,", "    normalize_default_sql,", "    type_fingerprint,", ")", "from common.erd.triggers import ErdTrigger, parse_trigger_sql", "from test.unit.db.erd.registers import Divergence", "", "_TICKET_KEY = re.compile(r\"[A-Z][A-Z0-9]+-[0-9]+\")", "_PG_DIALECT = postgresql.dialect()", "_DDL_COMPILER = _PG_DIALECT.ddl_compiler(_PG_DIALECT, None)", "", "# Scoring's eight dimensions.", "TABLE_COMMENT = \"table_comment\"", "COLUMN_COMMENT = \"comment\"", "COLUMN_TYPE = \"type\"", "COLUMN_NULLABLE = \"nullable\"", "COLUMN_PRESENCE = \"column_presence\"", "TABLE_PRESENCE = \"table_presence\"", "ENUM_PRESENCE = \"enum_presence\"", "ENUM_MEMBERS = \"enum_members\"", "# Keys, constraints, indexes and defaults.", "PK_COLUMNS = \"pk_columns\"", "FK_PRESENCE = \"fk_presence\"", "FK_ACTION = \"fk_action\"", "UNIQUE_PRESENCE = \"unique_presence\"", "UNIQUE_COLUMNS = \"unique_columns\"", "UNIQUE_OPTIONS = \"unique_options\"", "COLUMN_GENERATED = \"generated\"", "INDEX_PRESENCE = \"index_presence\"", "INDEX_DEFINITION = \"index_definition\"", "SERVER_DEFAULT = \"server_default\"", "CHECK_PRESENCE = \"check_presence\"", "CHECK_EXPRESSION = \"check_expression\"", "# Triggers, compared as parsed DDL on both sides.", "TRIGGER_PRESENCE = \"trigger_presence\"", "TRIGGER_DEFINITION = \"trigger_definition\"", "TRIGGER_FUNCTION = \"trigger_function\"", "", "# The ERD's FK action, taken from the SQL exports: none declares ON DELETE/ON UPDATE.", "DEFAULT_FK_ACTION = \"ON DELETE NO ACTION ON UPDATE NO ACTION\"", "", "", "@dataclass(frozen=True)", "class Comparison:", "    \"\"\"One comparable cell: an object, a dimension, and both sides' values.\"\"\"", "", "    obj: str", "    dim: str", "    erd: object", "    model: object", "", "    @property", "    def key(self) -> tuple[str, str]:", "        \"\"\"The ``(object, dimension)`` key a register entry is stored under.\"\"\"", "        return (self.obj, self.dim)", "", "    @property", "    def differs(self) -> bool:", "        \"\"\"Whether the cell is drift.\"\"\"", "        return self.erd != self.model", "", "", "# --- Model-side readers ------------------------------------------------------", "", "", "def _compile(clause: object) -> str:", "    \"\"\"Render a SQL clause the way Postgres stores it: literal values, no table prefix.\"\"\"", "    if isinstance(clause, str):", "        clause = sa.text(clause)", "    compiled = clause.compile(  # type: ignore[attr-defined]", "        dialect=_PG_DIALECT, compile_kwargs={\"literal_binds\": True, \"include_table\": False}", "    )", "    return str(compiled)", "", "", "def model_tables(metadata: sa.MetaData) -> dict[str, sa.Table]:", "    \"\"\"Every table in ``metadata``, keyed ``schema.table``.\"\"\"", "    return {f\"{table.schema}.{table.name}\": table for table in metadata.tables.values()}", "", "", "def model_type(column: sa.Column) -> str:", "    \"\"\"Canonical type fingerprint for a model column.\"\"\"", "    column_type = column.type", "    is_list = isinstance(column_type, sa.ARRAY)", "    if is_list:", "        column_type = column_type.item_type", "    if isinstance(column_type, sa.Enum) and column_type.name:", "        return type_fingerprint(f\"{column_type.schema}.{column_type.name}\", is_list=is_list)", "    return type_fingerprint(column_type.compile(dialect=_PG_DIALECT), is_list=is_list)", "", "", "def model_server_default(column: sa.Column) -> str:", "    \"\"\"The column's ``server_default`` as DDL renders it, normalized; ``\"\"`` when absent.", "", "    A Python-side ``default=`` never reaches the database, so it reads as no default.", "    \"\"\"", "    rendered = _DDL_COMPILER.get_column_default_string(column)", "    return normalize_default_sql(rendered) if rendered is not None else \"\"", "", "", "def model_enums(metadata: sa.MetaData) -> dict[str, tuple[str, ...]]:", "    \"\"\"Every enum type the models declare, keyed ``schema.enum``.", "", "    Includes standalone enums bound with ``sa.Enum(..., metadata=metadata)``: an", "    ERD enum no column uses (a type only CHECKs or casts refer to) can only be", "    declared that way.", "", "    :raises AssertionError: If one ``schema.enum`` is declared with two member", "        tuples. Postgres has one type per name, so that database cannot exist.", "    \"\"\"", "    found: dict[str, dict[tuple[str, ...], list[str]]] = {}", "    on_columns: set[int] = set()", "", "    def _add(enum_type: sa.Enum, where: str) -> None:", "        key = f\"{enum_type.schema}.{enum_type.name}\"", "        found.setdefault(key, {}).setdefault(tuple(enum_type.enums), []).append(where)", "", "    for table in metadata.tables.values():", "        for column in table.columns:", "            column_type = column.type", "            if isinstance(column_type, sa.ARRAY):", "                column_type = column_type.item_type", "            if isinstance(column_type, sa.Enum) and column_type.name:", "                on_columns.add(id(column_type))", "                _add(column_type, f\"{table.schema}.{table.name}.{column.name}\")", "    # A metadata-bound enum registers its CREATE TYPE hook here; no public registry exists.", "    for listener in metadata.dispatch.before_create:", "        enum_type = getattr(listener, \"target\", None)", "        if isinstance(enum_type, sa.Enum) and enum_type.name and id(enum_type) not in on_columns:", "            _add(enum_type, \"standalone sa.Enum(metadata=...)\")", "", "    conflicts = {key: variants for key, variants in found.items() if len(variants) > 1}", "    assert not conflicts, \"\\n\".join(", "        [", "            \"The models declare the same enum type with different members. Postgres \"", "            \"has one type per name, so reconcile them before parity can mean anything:\",", "            *[", "                f\"  {key}:\\n\"", "                + \"\\n\".join(", "                    f\"    {list(members)} declared by {', '.join(sorted(columns))}\"", "                    for members, columns in sorted(variants.items())", "                )", "                for key, variants in sorted(conflicts.items())", "            ],", "        ]", "    )", "    return {key: next(iter(variants)) for key, variants in found.items()}", "", "", "def _model_uniques(table: sa.Table) -> dict[str, tuple[str, ...]]:", "    found: dict[str, tuple[str, ...]] = {}", "    for constraint in table.constraints:", "        if isinstance(constraint, sa.UniqueConstraint):", "            columns = tuple(column.name for column in constraint.columns)", "            found[constraint.name or f\"<unnamed unique ({', '.join(columns)})>\"] = columns", "    return found", "", "", "def _model_unique_options(table: sa.Table) -> dict[str, str]:", "    \"\"\"Each unique constraint's Postgres options Luna cannot express; ``\"\"`` when none.\"\"\"", "    found: dict[str, str] = {}", "    for constraint in table.constraints:", "        if isinstance(constraint, sa.UniqueConstraint):", "            columns = tuple(column.name for column in constraint.columns)", "            options = constraint.dialect_options[\"postgresql\"]", "            text = \"nulls not distinct\" if options[\"nulls_not_distinct\"] else \"\"", "            if options[\"include\"]:", "                text = f\"{text} include=({', '.join(options['include'])})\".strip()", "            found[constraint.name or f\"<unnamed unique ({', '.join(columns)})>\"] = text", "    return found", "", "", "def index_definition(", "    unique: bool,", "    columns: Iterable[str],", "    where: str,", "    expression: str,", "    *,", "    method: str = \"\",", "    ops: Mapping[str, str] | None = None,", "    include: Iterable[str] = (),", "    nulls_not_distinct: bool = False,", ") -> str:", "    \"\"\"One index's comparable definition, as a single string that is easy to pin.", "", "    Access method, operator classes, ``INCLUDE`` and ``NULLS NOT DISTINCT`` are", "    appended only when set, so an index Luna can express reads the same as before.", "    \"\"\"", "    text = f\"unique={unique} columns=({', '.join(columns)})\"", "    if where:", "        text += f\" where={normalize_check_sql(where)}\"", "    if expression:", "        text += f\" expression={normalize_check_sql(expression)}\"", "    if method and method.lower() != \"btree\":", "        text += f\" using={method.lower()}\"", "    if ops:", "        text += \" ops=(\" + \", \".join(f\"{c} {o.lower()}\" for c, o in sorted(ops.items())) + \")\"", "    if include := list(include):", "        text += f\" include=({', '.join(include)})\"", "    if nulls_not_distinct:", "        text += \" nulls_not_distinct\"", "    return text", "", "", "def _model_indexes(table: sa.Table) -> dict[str, str]:", "    found: dict[str, str] = {}", "    for index in table.indexes:", "        columns: list[str] = []", "        expressions: list[str] = []", "        for expression in index.expressions:", "            if isinstance(expression, sa.Column):", "                columns.append(expression.name)", "            else:", "                expressions.append(_compile(expression))", "        options = index.dialect_options[\"postgresql\"]", "        where = _compile(options[\"where\"]) if options[\"where\"] is not None else \"\"", "        name = index.name or f\"<unnamed index ({', '.join(columns)})>\"", "        found[name] = index_definition(", "            bool(index.unique),", "            columns,", "            where,", "            \", \".join(expressions),", "            method=options[\"using\"] or \"\",", "            ops=options[\"ops\"],", "            include=[str(getattr(c, \"name\", c)) for c in options[\"include\"] or ()],", "            nulls_not_distinct=bool(options[\"nulls_not_distinct\"]),", "        )", "    return found", "", "", "def model_generated(column: sa.Column) -> str:", "    \"\"\"How Postgres generates the column (computed expression or identity); ``\"\"`` when not.\"\"\"", "    if column.computed is not None:", "        return f\"generated always as ({normalize_check_sql(_compile(column.computed.sqltext))})\"", "    if column.identity is not None:", "        return f\"identity {'always' if column.identity.always else 'by default'}\"", "    return \"\"", "", "", "def _model_checks(table: sa.Table) -> dict[str, str]:", "    found: dict[str, str] = {}", "    for constraint in table.constraints:", "        if isinstance(constraint, sa.CheckConstraint):", "            expression = normalize_check_sql(_compile(constraint.sqltext))", "            found[constraint.name or f\"<unnamed check: {expression}>\"] = expression", "    return found", "", "", "def _fk_identity(", "    child_table: str, child_columns: Iterable[str], parent_table: str, parent_columns: Iterable[str]", ") -> str:", "    return f\"{child_table}({','.join(child_columns)})->{parent_table}({','.join(parent_columns)})\"", "", "", "def _model_foreign_keys(key: str, table: sa.Table) -> dict[str, str]:", "    \"\"\"Each FK on ``table``, by identity, mapped to its rendered ON DELETE/ON UPDATE.\"\"\"", "    found: dict[str, str] = {}", "    for constraint in table.foreign_key_constraints:", "        parents = [element.target_fullname.rsplit(\".\", 1) for element in constraint.elements]", "        parent_tables = {parent[0] for parent in parents}", "        parent_table = parent_tables.pop() if len(parent_tables) == 1 else \"|\".join(parent_tables)", "        identity = _fk_identity(", "            key, constraint.column_keys, parent_table, [parent[-1] for parent in parents]", "        )", "        ondelete = (constraint.ondelete or \"NO ACTION\").upper()", "        onupdate = (constraint.onupdate or \"NO ACTION\").upper()", "        found[identity] = f\"ON DELETE {ondelete} ON UPDATE {onupdate}\"", "    return found", "", "", "# --- Comparison --------------------------------------------------------------", "", "", "def _presence_and_value(", "    rows: list[Comparison],", "    prefix: str,", "    erd: Mapping[str, object],", "    model: Mapping[str, object],", "    presence_dim: str,", "    value_dim: str,", ") -> None:", "    \"\"\"Emit a presence cell for each one-sided name and a value cell for each shared one.\"\"\"", "    for name in sorted(set(erd) ^ set(model)):", "        rows.append(Comparison(f\"{prefix}.{name}\", presence_dim, name in erd, name in model))", "    for name in sorted(set(erd) & set(model)):", "        rows.append(Comparison(f\"{prefix}.{name}\", value_dim, erd[name], model[name]))", "", "", "def _table_rows(key: str, erd_table: ErdTable, model_table: sa.Table) -> list[Comparison]:", "    rows = [", "        Comparison(", "            key,", "            TABLE_COMMENT,", "            normalize_comment(erd_table.desc),", "            normalize_comment(model_table.comment),", "        )", "    ]", "    model_columns = set(model_table.columns.keys())", "    for name in sorted(model_columns ^ set(erd_table.columns)):", "        rows.append(", "            Comparison(", "                f\"{key}.{name}\", COLUMN_PRESENCE, name in erd_table.columns, name in model_columns", "            )", "        )", "    for name in sorted(model_columns & set(erd_table.columns)):", "        model_column, erd_column = model_table.columns[name], erd_table.columns[name]", "        obj = f\"{key}.{name}\"", "        rows.append(", "            Comparison(", "                obj,", "                COLUMN_COMMENT,", "                normalize_comment(erd_column.comment),", "                normalize_comment(model_column.comment),", "            )", "        )", "        rows.append(Comparison(obj, COLUMN_TYPE, erd_column.fingerprint, model_type(model_column)))", "        rows.append(Comparison(obj, COLUMN_NULLABLE, erd_column.nn, not model_column.nullable))", "        rows.append(", "            Comparison(", "                obj,", "                SERVER_DEFAULT,", "                normalize_default_sql(erd_column.default),", "                model_server_default(model_column),", "            )", "        )", "        rows.append(", "            Comparison(obj, COLUMN_GENERATED, erd_column.generated, model_generated(model_column))", "        )", "", "    rows.append(", "        Comparison(", "            key,", "            PK_COLUMNS,", "            tuple(erd_table.primary_key),", "            tuple(column.name for column in model_table.primary_key.columns),", "        )", "    )", "    _presence_and_value(", "        rows,", "        key,", "        {unique.name: unique.columns for unique in erd_table.unique_constraints},", "        _model_uniques(model_table),", "        UNIQUE_PRESENCE,", "        UNIQUE_COLUMNS,", "    )", "    # Luna cannot express unique-constraint options, so the ERD side is always \"\".", "    model_unique_options = _model_unique_options(model_table)", "    for name in sorted({u.name for u in erd_table.unique_constraints} & set(model_unique_options)):", "        rows.append(Comparison(f\"{key}.{name}\", UNIQUE_OPTIONS, \"\", model_unique_options[name]))", "    _presence_and_value(", "        rows,", "        key,", "        {", "            index.name: index_definition(", "                index.unique, index.columns, index.where, index.expression, method=index.method", "            )", "            for index in erd_table.indexes", "        },", "        _model_indexes(model_table),", "        INDEX_PRESENCE,", "        INDEX_DEFINITION,", "    )", "    _presence_and_value(", "        rows,", "        key,", "        {", "            check.name: normalize_check_sql(check.expression)", "            for check in erd_table.check_constraints", "        },", "        _model_checks(model_table),", "        CHECK_PRESENCE,", "        CHECK_EXPRESSION,", "    )", "    return rows", "", "", "def model_triggers(ddl: Iterable[str]) -> dict[str, ErdTrigger]:", "    \"\"\"The models' trigger DDL strings, parsed and keyed ``schema.table.trigger``.", "", "    :raises ErdSpecError: If a string is not one trigger function plus its trigger.", "    :raises AssertionError: If two strings declare the same trigger.", "    \"\"\"", "    found: dict[str, ErdTrigger] = {}", "    for index, text in enumerate(ddl):", "        trigger = parse_trigger_sql(text, f\"model trigger DDL #{index}\")", "        assert trigger.key not in found, f\"the models declare trigger {trigger.key} twice\"", "        found[trigger.key] = trigger", "    return found", "", "", "def _trigger_rows(spec: ErdSpec, shared: set[str], ddl: Iterable[str]) -> list[Comparison]:", "    erd = {trigger.key: trigger for trigger in spec.triggers if trigger.table in shared}", "    model = model_triggers(ddl)", "    rows: list[Comparison] = []", "    for key in sorted(set(erd) ^ set(model)):", "        rows.append(Comparison(key, TRIGGER_PRESENCE, key in erd, key in model))", "    for key in sorted(set(erd) & set(model)):", "        rows.append(Comparison(key, TRIGGER_DEFINITION, erd[key].definition, model[key].definition))", "        rows.append(", "            Comparison(", "                key, TRIGGER_FUNCTION, erd[key].function_definition, model[key].function_definition", "            )", "        )", "    return rows", "", "", "def build_comparisons(", "    spec: ErdSpec,", "    metadata: sa.MetaData,", "    trigger_ddl: Iterable[str] = (),", "    deferred: Collection[str] = frozenset(),", ") -> tuple[Comparison, ...]:", "    \"\"\"Every comparable cell between one ERD and the metadata bound to it, sorted.", "", "    Only called for a ``RESOLVED`` binding, so a table on one side only is a cell", "    in both directions: a model-only table is unreviewed design, and an ERD-only", "    table is a missing model. The exception is an ERD-only table in ``deferred``,", "    which a later ticket builds: it produces no cell. ERD triggers, FKs and", "    indexes are compared on shared tables only; every model trigger is compared.", "    \"\"\"", "    model = model_tables(metadata)", "    shared = sorted(set(model) & set(spec.tables))", "    rows: list[Comparison] = []", "", "    for key in shared:", "        rows.extend(_table_rows(key, spec.tables[key], model[key]))", "    for key in sorted(set(model) ^ set(spec.tables)):", "        if key in deferred and key not in model:", "            continue", "        rows.append(Comparison(key, TABLE_PRESENCE, key in spec.tables, key in model))", "", "    # FK identity is name-free, so a retargeted FK reads as one missing plus one extra.", "    shared_set = set(shared)", "    erd_fks = {fk.identity for fk in spec.foreign_keys if fk.child_table in shared_set}", "    model_fks: dict[str, str] = {}", "    for key in shared:", "        model_fks.update(_model_foreign_keys(key, model[key]))", "    for identity in sorted(erd_fks | set(model_fks)):", "        rows.append(Comparison(identity, FK_PRESENCE, identity in erd_fks, identity in model_fks))", "    for identity, action in sorted(model_fks.items()):", "        rows.append(Comparison(identity, FK_ACTION, DEFAULT_FK_ACTION, action))", "", "    enums = model_enums(metadata)", "    for key in sorted(set(enums) | set(spec.enums)):", "        in_erd, in_model = key in spec.enums, key in enums", "        rows.append(Comparison(key, ENUM_PRESENCE, in_erd, in_model))", "        if in_erd and in_model:", "            # Ordered: Postgres enum declaration order defines the type's sort order.", "            rows.append(Comparison(key, ENUM_MEMBERS, spec.enums[key].members, enums[key]))", "", "    rows.extend(_trigger_rows(spec, shared_set, trigger_ddl))", "    return tuple(sorted(rows, key=lambda row: (row.obj, row.dim)))", "", "", "@lru_cache(maxsize=None)", "def comparisons_for(binding: ErdBinding) -> tuple[Comparison, ...]:", "    \"\"\"The binding's cells. A ``PENDING`` binding, or one whose metadata is absent, has none.\"\"\"", "    if binding.state is not BindingState.RESOLVED:", "        return ()", "    metadata = erd_bindings.resolve_metadata(binding)", "    if metadata is None:", "        return ()", "    trigger_ddl = erd_bindings.resolve_triggers(binding) or ()", "    return build_comparisons(", "        load_erd_spec(binding.erd_dir), metadata, trigger_ddl, binding.deferred_table_keys", "    )", "", "", "# --- Register checks ---------------------------------------------------------", "", "", "def drift_failures(", "    cells: Iterable[Comparison], registers: Mapping[tuple[str, str], Divergence], version: str", ") -> list[str]:", "    \"\"\"A message for every differing cell that no register entry accepts with these values.\"\"\"", "    failures: list[str] = []", "    for row in cells:", "        if not row.differs:", "            continue", "        entry = registers.get(row.key)", "        if entry is None:", "            failures.append(", "                f\"{row.obj} [{row.dim}] differs from ERD v{version}.\\n\"", "                f\"  ERD:   {row.erd!r}\\n\"", "                f\"  model: {row.model!r}\"", "            )", "        elif (entry.erd, entry.model) != (row.erd, row.model):", "            failures.append(", "                f\"{row.obj} [{row.dim}] is an accepted divergence, but the values moved.\\n\"", "                f\"  recorded ERD:   {entry.erd!r}\\n\"", "                f\"  actual ERD:     {row.erd!r}\\n\"", "                f\"  recorded model: {entry.model!r}\\n\"", "                f\"  actual model:   {row.model!r}\"", "            )", "    return failures", "", "", "def stale_entries(", "    cells: Iterable[Comparison], registers: Mapping[tuple[str, str], Divergence]", ") -> list[str]:", "    \"\"\"A message for every register entry whose cell is gone or no longer differs.\"\"\"", "    by_key = {row.key: row for row in cells}", "    stale: list[str] = []", "    for key in sorted(registers):", "        row = by_key.get(key)", "        if row is None:", "            stale.append(f\"{key[0]} [{key[1]}] is registered but no longer compared. Delete it.\")", "        elif not row.differs:", "            stale.append(f\"{key[0]} [{key[1]}] now matches the ERD. Delete its register entry.\")", "    return stale", "", "", "def missing_table_problems(", "    spec: ErdSpec, metadata: sa.MetaData, deferred: Collection[str]", ") -> list[str]:", "    \"\"\"ERD-only tables on a resolved binding that the binding does not defer.\"\"\"", "    return [", "        f\"{key} is in the ERD but has no model. Add the model, or, if a later ticket \"", "        \"builds it, add it to the binding's deferred_tables with that ticket.\"", "        for key in sorted(set(spec.tables) - set(model_tables(metadata)) - set(deferred))", "    ]", "", "", "def overlap_problems(", "    spec: ErdSpec, metadata: sa.MetaData, deferred: Collection[str], cell_count: int", ") -> list[str]:", "    \"\"\"The resolved-binding floor: every ERD table bar the deferred has a model, and cells exist.\"\"\"", "    omitted = set(spec.tables) & set(deferred)", "    owned_model_tables = set(model_tables(metadata)) & set(spec.tables)", "    problems: list[str] = []", "    expected = len(spec.tables) - len(omitted)", "    if len(owned_model_tables) != expected:", "        problems.append(", "            f\"{len(owned_model_tables)} ERD tables have models; expected {expected} \"", "            f\"({len(spec.tables)} in the ERD minus {len(omitted)} deferred).\"", "        )", "    if cell_count <= 0:", "        problems.append(\"the binding is RESOLVED but produced no comparison cells\")", "    return problems", "", "", "def deferred_table_problems(", "    binding: ErdBinding, spec: ErdSpec, metadata: sa.MetaData | None", ") -> list[str]:", "    \"\"\"Each deferred table names a real ERD table and a ticket, once, and has no model yet.", "", "    ``metadata`` is ``None`` while the models have not landed; the model check then waits.", "    \"\"\"", "    problems: list[str] = []", "    seen: set[str] = set()", "    modelled = set(model_tables(metadata)) if metadata is not None else set()", "    for deferred in binding.deferred_tables:", "        key = deferred.table", "        if key in seen:", "            problems.append(f\"{key} is deferred twice on binding {binding.name!r}.\")", "        seen.add(key)", "        if key not in spec.tables:", "            problems.append(", "                f\"{key} is deferred on binding {binding.name!r} but is not in ERD \"", "                f\"v{spec.version}. Fix the name, or delete it if the ERD dropped the table.\"", "            )", "        if not _TICKET_KEY.fullmatch(deferred.ticket):", "            problems.append(f\"{key} is deferred without a ticket key: {deferred.ticket!r}.\")", "        if not deferred.reason.strip():", "            problems.append(f\"{key} is deferred without a reason.\")", "        if key in modelled:", "            problems.append(", "                f\"{key} is deferred on binding {binding.name!r} but now has a model. \"", "                \"Delete it from deferred_tables.\"", "            )", "    return problems", "", "", "def floor_problems(binding: ErdBinding, spec: ErdSpec) -> list[str]:", "    \"\"\"The ERD-side floor: a broken, truncated or empty ``.dmm`` parses to too little.\"\"\"", "    problems: list[str] = []", "    if len(spec.tables) < binding.min_tables:", "        problems.append(", "            f\"ERD {spec.source.name} parsed to {len(spec.tables)} tables, below the floor of \"", "            f\"{binding.min_tables}. Check the vendored .dmm is the full model.\"", "        )", "    if spec.column_count < binding.min_columns:", "        problems.append(", "            f\"ERD {spec.source.name} parsed to {spec.column_count} columns, below the floor of \"", "            f\"{binding.min_columns}. Check the vendored .dmm is the full model.\"", "        )", "    if len(spec.triggers) < binding.min_triggers:", "        problems.append(", "            f\"ERD {spec.source.name} parsed to {len(spec.triggers)} triggers, below the floor of \"", "            f\"{binding.min_triggers}. Check the vendored .dmm is the full model.\"", "        )", "    return problems", "", "", "def binding_state_problems(binding: ErdBinding) -> list[str]:", "    \"\"\"Whether the declared state matches whether the metadata and trigger DDL resolve.\"\"\"", "    metadata = erd_bindings.resolve_metadata(binding)", "    triggers = erd_bindings.resolve_triggers(binding)", "    if binding.state is BindingState.PENDING:", "        landed = [", "            target", "            for target, value in (", "                (binding.metadata_import, metadata),", "                (binding.triggers_import, triggers),", "            )", "            if value is not None", "        ]", "        if landed:", "            return [", "                f\"{binding.name} is PENDING but {', '.join(landed)} resolves. The models \"", "                \"have landed: flip the binding to RESOLVED and set migrations_dir.\"", "            ]", "        return []", "    problems: list[str] = []", "    if metadata is None:", "        problems.append(f\"{binding.name} is RESOLVED but {binding.metadata_module} does not exist.\")", "    if triggers is None:", "        problems.append(", "            f\"{binding.name} is RESOLVED but {binding.triggers_module} does not exist; declare \"", "            \"its trigger DDL there (an empty tuple if the schema has none).\"", "        )", "    if not binding.migrations_dir:", "        problems.append(f\"{binding.name} is RESOLVED but has no migrations_dir.\")", "    return problems", "", "", "# A trigger, or a function declared RETURNS trigger. Any other function is not trigger", "# state and is skipped; a trigger function with arguments still matches, so the parser", "# rejects it. The header scan stops at the body ($ or ;) so it never reads past it.", "_CREATES_TRIGGER_SQL = re.compile(", "    r\"\\bCREATE\\s+(?:CONSTRAINT\\s+)?TRIGGER\\b\"", "    r\"|\\bCREATE\\s+(?:OR\\s+REPLACE\\s+)?FUNCTION\\b[^;$]*?\\bRETURNS\\s+trigger\\b\",", "    re.IGNORECASE,", ")", "_DROP_TRIGGER_SQL = re.compile(", "    r\"\\bDROP\\s+TRIGGER\\s+(?:IF\\s+EXISTS\\s+)?(?P<name>\\w+)\\s+ON\\s+(?P<table>\\w+\\.\\w+)\"", "    r\"(?:\\s+(?:CASCADE|RESTRICT))?\\s*;?\",", "    re.IGNORECASE,", ")", "_DROP_TABLE_SQL = re.compile(", "    r\"\\bDROP\\s+TABLE\\s+(?:IF\\s+EXISTS\\s+)?(?P<tables>\\w+\\.\\w+(?:\\s*,\\s*\\w+\\.\\w+)*)\"", "    r\"(?:\\s+(?:CASCADE|RESTRICT))?\\s*;?\",", "    re.IGNORECASE,", ")", "_RENAME_TABLE_SQL = re.compile(", "    r\"\\bALTER\\s+TABLE\\s+(?:IF\\s+EXISTS\\s+)?(?:ONLY\\s+)?(?P<table>\\w+\\.\\w+)\\s+\"", "    r\"(?:RENAME\\s+TO|SET\\s+SCHEMA)\\b\",", "    re.IGNORECASE,", ")", "_DROP_FUNCTION_SQL = re.compile(r\"\\bDROP\\s+FUNCTION\\b[^;]*;?\", re.IGNORECASE)", "# Statements that change trigger state in ways the replay does not model.", "_UNMODELLED_TRIGGER_SQL = re.compile(", "    r\"\\bALTER\\s+(?:TRIGGER|FUNCTION|ROUTINE)\\b\"", "    r\"|\\b(?:ENABLE|DISABLE)\\s+(?:ALWAYS\\s+|REPLICA\\s+)?TRIGGER\\b\"", "    r\"|\\bDROP\\s+SCHEMA\\b|\\bDROP\\s+FUNCTION\\b[^;]*\\bCASCADE\\b\",", "    re.IGNORECASE,", ")", "_UNQUALIFIED_DROP_SQL = re.compile(r\"\\bDROP\\s+(?:TRIGGER|TABLE)\\b\", re.IGNORECASE)", "# Only straight-line code and for-loops over literal tuples run every replayed call exactly once.", "_CONDITIONAL_NODES = (", "    ast.If,", "    ast.IfExp,", "    ast.While,", "    ast.Try,", "    ast.TryStar,", "    ast.Match,", "    ast.BoolOp,", "    ast.FunctionDef,", "    ast.AsyncFunctionDef,", "    ast.Lambda,", "    ast.ClassDef,", "    ast.comprehension,", ")", "_RAW_EXECUTE_METHODS = frozenset({\"execute\", \"exec_driver_sql\"})", "_REPLAYED_OPS = frozenset({\"op.execute\", \"op.drop_table\", \"op.rename_table\"})", "", "", "@dataclass(frozen=True)", "class _Revision:", "    \"\"\"One Alembic revision file, reduced to what the trigger replay needs.\"\"\"", "", "    path: Path", "    revision: str", "    parents: tuple[str, ...]", "    steps: tuple[tuple[int, str, str], ...]", "    \"\"\"``(line, kind, value)`` in source order: ``sql``, ``drop_table`` or ``rename_table``.\"\"\"", "", "    problems: tuple[str, ...] = ()", "    \"\"\"What the file does that the replay cannot read; each one fails the guard.\"\"\"", "", "", "def _module_strings(tree: ast.Module) -> dict[str, tuple[str, ...]]:", "    \"\"\"Module-level names bound to a string literal, or to a tuple or list of them.\"\"\"", "    found: dict[str, tuple[str, ...]] = {}", "    for node in tree.body:", "        targets = node.targets if isinstance(node, ast.Assign) else [getattr(node, \"target\", None)]", "        value = getattr(node, \"value\", None)", "        if isinstance(value, ast.Constant) and isinstance(value.value, str):", "            strings: tuple[str, ...] | None = (value.value,)", "        elif isinstance(value, ast.Tuple | ast.List) and all(", "            isinstance(item, ast.Constant) and isinstance(item.value, str) for item in value.elts", "        ):", "            strings = tuple(item.value for item in value.elts)  # type: ignore[attr-defined]", "        else:", "            strings = None", "        for target in targets:", "            if strings is not None and isinstance(target, ast.Name):", "                found[target.id] = strings", "    return found", "", "", "def _literal_strings(", "    node: ast.AST | None, names: Mapping[str, tuple[str, ...] | None]", ") -> tuple[str, ...] | None:", "    \"\"\"The SQL an ``op.execute`` argument statically carries, or ``None`` if it is computed.\"\"\"", "    if isinstance(node, ast.Constant) and isinstance(node.value, str):", "        return (node.value,)", "    if isinstance(node, ast.Call) and ast.unparse(node.func) in (\"text\", \"sa.text\"):", "        return _literal_strings(node.args[0], names) if len(node.args) == 1 else None", "    if isinstance(node, ast.Name):", "        return names.get(node.id)", "    return None", "", "", "def _call_argument(call: ast.Call, position: int, keyword: str) -> ast.expr | None:", "    if len(call.args) > position:", "        return call.args[position]", "    return next((kw.value for kw in call.keywords if kw.arg == keyword), None)", "", "", "def _table_key(call: ast.Call, func: str) -> str | None:", "    \"\"\"``schema.table`` an ``op.drop_table``/``op.rename_table`` acts on, if both are literals.\"\"\"", "    if func == \"op.drop_table\":", "        table = _call_argument(call, 0, \"table_name\")", "        schema = next((kw.value for kw in call.keywords if kw.arg == \"schema\"), None)", "    else:", "        table = _call_argument(call, 0, \"old_table_name\")", "        schema = _call_argument(call, 2, \"schema\")", "    name, owner = _string_constant(table), _string_constant(schema)", "    return f\"{owner}.{name}\" if name and owner else None", "", "", "def _read_revision(path: Path) -> _Revision | str:", "    \"\"\"Parse one revision file, or return why it cannot take part in the replay.\"\"\"", "    tree = ast.parse(path.read_text(encoding=\"utf-8\"), filename=str(path))", "    header: dict[str, object] = {}", "    for node in tree.body:", "        target = node.targets[0] if isinstance(node, ast.Assign) else getattr(node, \"target\", None)", "        if isinstance(target, ast.Name) and target.id in (\"revision\", \"down_revision\"):", "            header[target.id] = ast.literal_eval(node.value)  # type: ignore[attr-defined]", "    revision, down = header.get(\"revision\"), header.get(\"down_revision\")", "    if not isinstance(revision, str):", "        return f\"{path} has no literal revision id, so the trigger replay cannot order it.\"", "    parents = (down,) if isinstance(down, str) else tuple(down or ())  # type: ignore[arg-type]", "", "    problems = _helper_problems(tree, path)", "    upgrade = next(", "        (n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == \"upgrade\"), None", "    )", "    steps: list[tuple[int, int, str, str]] = []", "    if upgrade is not None:", "        steps, upgrade_problems = _upgrade_steps(upgrade, _module_strings(tree), path)", "        problems.extend(upgrade_problems)", "    # Position only: strings from one looped tuple share it and must keep tuple order.", "    ordered = tuple(", "        (line, kind, value) for line, _, kind, value in sorted(steps, key=lambda s: s[:2])", "    )", "    return _Revision(path, revision, parents, ordered, tuple(problems))", "", "", "def _helper_problems(tree: ast.Module, path: Path) -> list[str]:", "    \"\"\"SQL-running calls in module-level functions other than ``upgrade``/``downgrade``.\"\"\"", "    return [", "        f\"{path}:{call.lineno} runs {ast.unparse(call.func)} inside {helper.name}(), which the \"", "        \"trigger replay does not follow; call it from upgrade() directly.\"", "        for helper in tree.body", "        if isinstance(helper, ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef)", "        and helper.name not in (\"upgrade\", \"downgrade\")", "        for call in ast.walk(helper)", "        if isinstance(call, ast.Call) and _runs_sql(call)", "    ]", "", "", "def _upgrade_steps(", "    upgrade: ast.FunctionDef, module_names: Mapping[str, tuple[str, ...]], path: Path", ") -> tuple[list[tuple[int, int, str, str]], list[str]]:", "    \"\"\"``(line, col, kind, value)`` for each replayed call in ``upgrade``, and what it cannot read.\"\"\"", "    # A name rebound inside upgrade() no longer holds its module-level string.", "    rebound = _bound_names(upgrade.body)", "    outer: dict[str, tuple[str, ...] | None] = {", "        name: value for name, value in module_names.items() if name not in rebound", "    }", "    steps: list[tuple[int, int, str, str]] = []", "    problems: list[str] = []", "    parent = {id(child): node for node in ast.walk(upgrade) for child in ast.iter_child_nodes(node)}", "    for call in ast.walk(upgrade):", "        if not isinstance(call, ast.Call):", "            continue", "        func = ast.unparse(call.func)", "        where = f\"{path}:{call.lineno}\"", "        if _runs_sql(call) and _is_conditional(call, upgrade, parent):", "            problems.append(", "                f\"{where} runs {func} under a branch, loop or nested function the trigger \"", "                \"replay cannot evaluate; keep it in straight-line upgrade() code.\"", "            )", "            continue", "        if func == \"op.execute\":", "            names = _names_at(call, upgrade, parent, outer)", "            sql = _literal_strings(_call_argument(call, 0, \"sqltext\"), names)", "            if sql is None:", "                problems.append(", "                    f\"{where} passes op.execute SQL the trigger replay cannot read; use a \"", "                    \"string literal, or a module-level string or tuple of them.\"", "                )", "            steps.extend((call.lineno, call.col_offset, \"sql\", text) for text in sql or ())", "        elif func in (\"op.drop_table\", \"op.rename_table\"):", "            key = _table_key(call, func)", "            if key is None:", "                problems.append(", "                    f\"{where} calls {func} without a literal table name and schema=, so the \"", "                    \"trigger replay cannot tell which table's triggers it affects.\"", "                )", "            else:", "                steps.append((call.lineno, call.col_offset, func.removeprefix(\"op.\"), key))", "        elif _runs_sql(call):", "            problems.append(", "                f\"{where} runs SQL through {func}, which the trigger replay does not read; \"", "                \"use op.execute with literal SQL.\"", "            )", "    return steps, problems", "", "", "_NESTED_SCOPES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)", "_COMPREHENSIONS = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)", "", "", "def _bound_names(body: Iterable[ast.AST]) -> set[str]:", "    \"\"\"Names bound in the scope that owns ``body``, by Python's scoping rules.", "", "    Nested functions, lambdas and classes bind their own name only, plus any", "    name they declare ``global`` or ``nonlocal``; a comprehension binds only its", "    ``:=`` targets in the enclosing scope.", "    \"\"\"", "    bound: set[str] = set()", "    pending = list(body)", "    while pending:", "        node = pending.pop()", "        if isinstance(node, _NESTED_SCOPES):", "            if not isinstance(node, ast.Lambda):", "                bound.add(node.name)", "            bound.update(", "                name", "                for inner in ast.walk(node)", "                if isinstance(inner, ast.Global | ast.Nonlocal)", "                for name in inner.names", "            )", "            continue", "        if isinstance(node, _COMPREHENSIONS):", "            bound.update(", "                inner.target.id", "                for inner in ast.walk(node)", "                if isinstance(inner, ast.NamedExpr) and isinstance(inner.target, ast.Name)", "            )", "            continue", "        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):", "            bound.add(node.id)", "        elif isinstance(node, ast.alias):", "            bound.add((node.asname or node.name).partition(\".\")[0])", "        elif isinstance(node, ast.ExceptHandler) and node.name:", "            bound.add(node.name)", "        pending.extend(ast.iter_child_nodes(node))", "    return bound", "", "", "def _names_at(", "    call: ast.AST,", "    upgrade: ast.FunctionDef,", "    parent: Mapping[int, ast.AST],", "    outer: Mapping[str, tuple[str, ...] | None],", ") -> dict[str, tuple[str, ...] | None]:", "    \"\"\"The strings each name holds at ``call``: ``outer``, then each enclosing loop's target.\"\"\"", "    loops: list[ast.For] = []", "    current = parent.get(id(call))", "    while current is not None and current is not upgrade:", "        if isinstance(current, ast.For) and isinstance(current.target, ast.Name):", "            loops.append(current)", "        current = parent.get(id(current))", "    names = dict(outer)", "    for loop in reversed(loops):", "        names[loop.target.id] = _literal_strings(loop.iter, names)  # type: ignore[union-attr]", "    return names", "", "", "def _is_conditional(node: ast.AST, upgrade: ast.FunctionDef, parent: Mapping[int, ast.AST]) -> bool:", "    \"\"\"Whether ``node`` might run other than as the replay records it.", "", "    The one loop the replay expands is ``for ddl in <strings>: op.execute(ddl)``", "    with no ``break``, ``continue`` or ``else``; any other enclosing loop is conditional.", "    \"\"\"", "    current = parent.get(id(node))", "    while current is not None and current is not upgrade:", "        if isinstance(current, (*_CONDITIONAL_NODES, ast.AsyncFor)):", "            return True", "        if isinstance(current, ast.For) and not _is_expanded_loop(current, node):", "            return True", "        current = parent.get(id(current))", "    return False", "", "", "def _is_expanded_loop(loop: ast.For, call: ast.AST) -> bool:", "    \"\"\"Whether ``loop`` executes its own target once per string, as the replay expands it.\"\"\"", "    return (", "        isinstance(loop.target, ast.Name)", "        and not loop.orelse", "        and not any(isinstance(n, ast.Break | ast.Continue) for n in ast.walk(loop))", "        and isinstance(call, ast.Call)", "        and ast.unparse(call.func) == \"op.execute\"", "        and ast.unparse(_call_argument(call, 0, \"sqltext\") or ast.Constant(None)) == loop.target.id", "    )", "", "", "def _runs_sql(call: ast.Call) -> bool:", "    \"\"\"Whether ``call`` is a replayed ``op.*`` call or a raw ``.execute``/``.exec_driver_sql``.\"\"\"", "    func = call.func", "    return ast.unparse(func) in _REPLAYED_OPS or (", "        isinstance(func, ast.Attribute) and func.attr in _RAW_EXECUTE_METHODS", "    )", "", "", "def _string_constant(node: ast.AST | None) -> str | None:", "    if isinstance(node, ast.Constant) and isinstance(node.value, str):", "        return node.value", "    return None", "", "", "def _in_upgrade_order(revisions: list[_Revision]) -> tuple[list[_Revision], list[str]]:", "    \"\"\"Revisions parents-first (ties by id, so the order is stable), and any ordering problems.\"\"\"", "    by_id: dict[str, _Revision] = {}", "    problems: list[str] = []", "    for rev in revisions:", "        if rev.revision in by_id:", "            problems.append(", "                f\"{rev.path} and {by_id[rev.revision].path} both declare revision \"", "                f\"{rev.revision!r}; Alembic cannot load the chain.\"", "            )", "        else:", "            by_id[rev.revision] = rev", "    problems.extend(", "        f\"{rev.path} names down_revision {parent!r}, which no revision in the chain defines.\"", "        for rev in revisions", "        for parent in rev.parents", "        if parent not in by_id", "    )", "    done: set[str] = set()", "    ordered: list[_Revision] = []", "    while len(ordered) < len(by_id):", "        ready = sorted(", "            rev_id", "            for rev_id, rev in by_id.items()", "            if rev_id not in done and all(p in done or p not in by_id for p in rev.parents)", "        )", "        if not ready:", "            problems.append(f\"the revision chain has a cycle among {sorted(set(by_id) - done)}.\")", "            break", "        done.add(ready[0])", "        ordered.append(by_id[ready[0]])", "    return ordered, problems", "", "", "def _replayed_triggers(", "    ordered: list[_Revision],", ") -> tuple[dict[str, ErdTrigger], list[str]]:", "    \"\"\"The triggers left in place after every ``upgrade()``, keyed like :func:`model_triggers`.\"\"\"", "    live: dict[str, ErdTrigger] = {}", "    problems: list[str] = []", "", "    def drop_table(table: str) -> None:", "        nonlocal live", "        live = {key: trig for key, trig in live.items() if trig.table != table}", "", "    def rename_table(table: str, where: str) -> None:", "        if any(trig.table == table for trig in live.values()):", "            problems.append(", "                f\"{where} renames or moves {table}, which has triggers; drop them first and \"", "                \"recreate them on the new table, so the replay can follow.\"", "            )", "", "    for rev in ordered:", "        for line, kind, value in rev.steps:", "            where = f\"{rev.path}:{line}\"", "            if kind == \"drop_table\":", "                drop_table(value)", "                continue", "            if kind == \"rename_table\":", "                rename_table(value, where)", "                continue", "            if _UNMODELLED_TRIGGER_SQL.search(value):", "                problems.append(", "                    f\"{where} changes trigger state in a way the replay does not model \"", "                    \"(ALTER TRIGGER/FUNCTION/ROUTINE, ENABLE/DISABLE TRIGGER, DROP SCHEMA, or \"", "                    \"DROP FUNCTION ... CASCADE); drop and recreate the trigger instead.\"", "                )", "            for dropped in _DROP_TRIGGER_SQL.finditer(value):", "                live.pop(f\"{dropped.group('table')}.{dropped.group('name')}\", None)", "            for dropped in _DROP_TABLE_SQL.finditer(value):", "                for table in re.split(r\"\\s*,\\s*\", dropped.group(\"tables\")):", "                    drop_table(table)", "            for renamed in _RENAME_TABLE_SQL.finditer(value):", "                rename_table(renamed.group(\"table\"), where)", "            remaining = _DROP_TABLE_SQL.sub(\"\", _DROP_TRIGGER_SQL.sub(\"\", value))", "            if _UNQUALIFIED_DROP_SQL.search(remaining):", "                problems.append(", "                    f\"{where} drops a trigger or table the replay cannot read; write \"", "                    \"DROP TRIGGER <name> ON <schema>.<table> or DROP TABLE <schema>.<table>.\"", "                )", "            created = _DROP_FUNCTION_SQL.sub(\"\", remaining)", "            if not _CREATES_TRIGGER_SQL.search(created):", "                continue", "            try:", "                trigger = parse_trigger_sql(created, where)", "            except ErdSpecError as error:", "                problems.append(f\"{error} Each op.execute string is one function plus its trigger.\")", "                continue", "            if trigger.key in live:", "                problems.append(", "                    f\"{where} creates {trigger.key}, which already exists at that \"", "                    f\"point; DROP TRIGGER {trigger.name} ON {trigger.table} first.\"", "                )", "            live[trigger.key] = trigger", "    return live, problems", "", "", "def migration_trigger_problems(binding: ErdBinding, repo_root: Path) -> list[str]:", "    \"\"\"Whether replaying a ``RESOLVED`` binding's revisions leaves exactly its ``TRIGGER_DDL``.", "", "    Each revision carries its own trigger SQL, so a later revision never changes", "    what an earlier one creates. The replay runs every ``upgrade()`` parents-first,", "    applying each ``op.execute`` (a function plus its trigger creates it;", "    ``DROP TRIGGER``, ``DROP TABLE`` and ``op.drop_table`` remove it), and the", "    triggers left must match ``TRIGGER_DDL`` definition for definition. It fails", "    closed: SQL it cannot read, or trigger changes it does not model, are problems.", "    \"\"\"", "    if binding.state is not BindingState.RESOLVED or not binding.migrations_dir:", "        return []", "    migrations = repo_root / binding.migrations_dir", "    if not migrations.is_dir():", "        return [f\"{binding.name}: migrations_dir {binding.migrations_dir} does not exist.\"]", "", "    problems: list[str] = []", "    revisions: list[_Revision] = []", "    for path in sorted(migrations.rglob(\"*.py\")):", "        tree = ast.parse(path.read_text(encoding=\"utf-8\"), filename=str(path))", "        if any(", "            (isinstance(node, ast.ImportFrom) and node.module == binding.triggers_module)", "            or (", "                isinstance(node, ast.Import)", "                and any(alias.name == binding.triggers_module for alias in node.names)", "            )", "            for node in ast.walk(tree)", "        ):", "            problems.append(", "                f\"{path} imports {binding.triggers_module}; a revision carries its own trigger \"", "                \"SQL, or replaying it later would also run triggers added after it.\"", "            )", "        if (migrations / \"versions\") in path.parents:", "            read = _read_revision(path)", "            if isinstance(read, str):", "                problems.append(read)", "            else:", "                problems.extend(read.problems)", "                revisions.append(read)", "", "    ordered, order_problems = _in_upgrade_order(revisions)", "    problems.extend(order_problems)", "    live, replay_problems = _replayed_triggers(ordered)", "    problems.extend(replay_problems)", "", "    declared = model_triggers(erd_bindings.resolve_triggers(binding) or ())", "    for key in sorted(set(declared) - set(live)):", "        problems.append(f\"{binding.triggers_import} declares {key}, but no revision creates it.\")", "    for key in sorted(set(live) - set(declared)):", "        problems.append(", "            f\"replaying the revisions leaves {key} in place, but {binding.triggers_import} \"", "            \"does not declare it.\"", "        )", "    for key in sorted(set(live) & set(declared)):", "        if (live[key].definition, live[key].function_definition) != (", "            declared[key].definition,", "            declared[key].function_definition,", "        ):", "            problems.append(", "                f\"{key}: the revisions' final definition differs from {binding.triggers_import}.\"", "            )", "    return problems", "", "", "def escaped_schema_references(src_root: Path, bindings: Iterable[ErdBinding]) -> list[str]:", "    \"\"\"Every owned-schema reference under ``src_root`` outside its binding's allowed paths.", "", "    Allowed paths are the binding's ``model_package`` (as a package folder or a", "    single module) and, for Alembic ``op.*`` and lightweight ``table()`` calls", "    and module-level constants only, its ``migrations_dir``; both resolve against", "    ``src_root.parent``. The binding registry (``src/common/erd/``) may name an", "    owned schema but never place an object in one.", "    \"\"\"", "    owner = {schema: binding for binding in bindings for schema in binding.owned_schemas}", "    registry = (src_root / \"common\" / \"erd\").resolve()", "    escapes: list[str] = []", "    for ref in scan_schema_references(src_root, owner):", "        binding = owner[ref.schema]", "        package_dir = src_root.joinpath(*binding.model_package.split(\".\"))", "        allowed = [package_dir]", "        if binding.migrations_dir and ref.migration_call:", "            allowed.append(src_root.parent / binding.migrations_dir)", "        if not ref.placement:", "            allowed.append(registry)", "        path = ref.path.resolve()", "        inside = path == package_dir.with_suffix(\".py\").resolve() or any(", "            folder.resolve() in path.parents for folder in allowed", "        )", "        if not inside:", "            verb = \"places an object in\" if ref.placement else \"names\"", "            escapes.append(", "                f\"{ref.path}:{ref.line} {verb} {ref.schema!r} ({ref.kind}) outside \"", "                f\"binding {binding.name!r} (model_package={binding.model_package}, \"", "                f\"migrations_dir={binding.migrations_dir}).\"", "            )", "    return escapes"], "blocks": [{"start": 1, "end": 75, "label": "Imports and module setup"}, {"start": 76, "end": 84, "label": "class Comparison"}, {"start": 85, "end": 89, "label": "Comparison.key"}, {"start": 90, "end": 98, "label": "Comparison.differs"}, {"start": 99, "end": 108, "label": "def _compile"}, {"start": 109, "end": 113, "label": "def model_tables"}, {"start": 114, "end": 124, "label": "def model_type"}, {"start": 125, "end": 133, "label": "def model_server_default"}, {"start": 134, "end": 182, "label": "def model_enums"}, {"start": 183, "end": 191, "label": "def _model_uniques"}, {"start": 192, "end": 205, "label": "def _model_unique_options"}, {"start": 206, "end": 237, "label": "def index_definition"}, {"start": 238, "end": 263, "label": "def _model_indexes"}, {"start": 264, "end": 272, "label": "def model_generated"}, {"start": 273, "end": 281, "label": "def _model_checks"}, {"start": 282, "end": 287, "label": "def _fk_identity"}, {"start": 288, "end": 306, "label": "def _model_foreign_keys"}, {"start": 307, "end": 321, "label": "def _presence_and_value"}, {"start": 322, "end": 409, "label": "def _table_rows"}, {"start": 410, "end": 423, "label": "def model_triggers"}, {"start": 424, "end": 439, "label": "def _trigger_rows"}, {"start": 440, "end": 487, "label": "def build_comparisons"}, {"start": 488, "end": 504, "label": "def comparisons_for"}, {"start": 505, "end": 530, "label": "def drift_failures"}, {"start": 531, "end": 545, "label": "def stale_entries"}, {"start": 546, "end": 556, "label": "def missing_table_problems"}, {"start": 557, "end": 574, "label": "def overlap_problems"}, {"start": 575, "end": 606, "label": "def deferred_table_problems"}, {"start": 607, "end": 627, "label": "def floor_problems"}, {"start": 628, "end": 710, "label": "def binding_state_problems"}, {"start": 711, "end": 724, "label": "class _Revision"}, {"start": 725, "end": 744, "label": "def _module_strings"}, {"start": 745, "end": 757, "label": "def _literal_strings"}, {"start": 758, "end": 763, "label": "def _call_argument"}, {"start": 764, "end": 775, "label": "def _table_key"}, {"start": 776, "end": 803, "label": "def _read_revision"}, {"start": 804, "end": 816, "label": "def _helper_problems"}, {"start": 817, "end": 869, "label": "def _upgrade_steps"}, {"start": 870, "end": 907, "label": "def _bound_names"}, {"start": 908, "end": 926, "label": "def _names_at"}, {"start": 927, "end": 942, "label": "def _is_conditional"}, {"start": 943, "end": 954, "label": "def _is_expanded_loop"}, {"start": 955, "end": 962, "label": "def _runs_sql"}, {"start": 963, "end": 968, "label": "def _string_constant"}, {"start": 969, "end": 1002, "label": "def _in_upgrade_order"}, {"start": 1003, "end": 1065, "label": "def _replayed_triggers"}, {"start": 1066, "end": 1129, "label": "def migration_trigger_problems"}, {"start": 1130, "end": 1161, "label": "def escaped_schema_references"}], "lineCount": 1161, "sha256": "7a244782ce69b71e36a4371c10d684d6587f15fae921d520c7812cb4a8279c2c", "endsWithNewline": true});
